### Step 1: Create the UI Panel

You can create a simple UI panel using HTML and JavaScript. After Effects supports HTML5 panels.

```html
<!DOCTYPE html>
<html>
<head>
    <title>ElevenLabs Voice Generator</title>
    <script src="https://code.jquery.com/jquery-3.6.0.min.js"></script>
    <style>
        body { font-family: Arial, sans-serif; }
        #voiceSelect { width: 100%; }
        #textInput { width: 100%; }
        button { width: 100%; }
    </style>
</head>
<body>
    <h1>ElevenLabs Voice Generator</h1>
    <select id="voiceSelect"></select>
    <textarea id="textInput" rows="4" placeholder="Enter text here..."></textarea>
    <button id="generateBtn">Generate Voice</button>
    <button id="generate3xBtn">Generate 3 Versions</button>

    <script>
        $(document).ready(function() {
            // Load voices from ElevenLabs API
            loadVoices();

            $('#generateBtn').on('click', function() {
                const voiceId = $('#voiceSelect').val();
                const text = $('#textInput').val();
                generateVoice(voiceId, text);
            });

            $('#generate3xBtn').on('click', function() {
                const voiceId = $('#voiceSelect').val();
                const text = $('#textInput').val();
                generateThreeVoices(voiceId, text);
            });
        });

        function loadVoices() {
            // Call to your backend to fetch voices
            $.get('/api/getVoices', function(data) {
                data.voices.forEach(voice => {
                    $('#voiceSelect').append(`<option value="${voice.id}">${voice.name}</option>`);
                });
            });
        }

        function generateVoice(voiceId, text) {
            $.post('/api/generateVoice', { voiceId, text }, function(data) {
                // Handle the response and download the MP3
                downloadFile(data.audioUrl);
            });
        }

        function generateThreeVoices(voiceId, text) {
            $.post('/api/generateThreeVoices', { voiceId, text }, function(data) {
                // Handle the response and download the MP3s
                downloadFile(data.audioUrl1);
                downloadFile(data.audioUrl2);
                downloadFile(data.audioUrl3);
            });
        }

        function downloadFile(url) {
            const a = document.createElement('a');
            a.href = url;
            a.download = 'generated_voice.mp3';
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
        }
    </script>
</body>
</html>
```

### Step 2: Backend API Integration

You will need a backend server to handle API requests to ElevenLabs. This can be done using Node.js, Express, or any other server-side technology.

#### Example Node.js Server

```javascript
const express = require('express');
const axios = require('axios');
const fs = require('fs');
const app = express();
const port = 3000;

app.use(express.json());
app.use(express.static('public')); // Serve your HTML panel

const ELEVENLABS_API_KEY = 'YOUR_ELEVENLABS_API_KEY';

app.get('/api/getVoices', async (req, res) => {
    try {
        const response = await axios.get('https://api.elevenlabs.io/voices', {
            headers: { 'Authorization': `Bearer ${ELEVENLABS_API_KEY}` }
        });
        res.json(response.data);
    } catch (error) {
        res.status(500).send(error.message);
    }
});

app.post('/api/generateVoice', async (req, res) => {
    const { voiceId, text } = req.body;
    try {
        const response = await axios.post('https://api.elevenlabs.io/generate', {
            voiceId,
            text
        }, {
            headers: { 'Authorization': `Bearer ${ELEVENLABS_API_KEY}` }
        });
        // Assuming the response contains a URL to the generated audio
        res.json({ audioUrl: response.data.audioUrl });
    } catch (error) {
        res.status(500).send(error.message);
    }
});

app.post('/api/generateThreeVoices', async (req, res) => {
    const { voiceId, text } = req.body;
    const audioUrls = [];
    try {
        for (let i = 0; i < 3; i++) {
            const response = await axios.post('https://api.elevenlabs.io/generate', {
                voiceId,
                text
            }, {
                headers: { 'Authorization': `Bearer ${ELEVENLABS_API_KEY}` }
            });
            audioUrls.push(response.data.audioUrl);
        }
        res.json({ audioUrl1: audioUrls[0], audioUrl2: audioUrls[1], audioUrl3: audioUrls[2] });
    } catch (error) {
        res.status(500).send(error.message);
    }
});

app.listen(port, () => {
    console.log(`Server running at http://localhost:${port}`);
});
```

