<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Flappy Bird Clone</title>
    <style>
        body { margin: 0; overflow: hidden; }
        canvas { display: block; }
    </style>
</head>
<body>
<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
<script>
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
    const renderer = new THREE.WebGLRenderer();
    renderer.setSize(window.innerWidth, window.innerHeight);
    document.body.appendChild(renderer.domElement);

    const birdGeometry = new THREE.BoxGeometry(0.5, 0.5, 0.5);
    const birdMaterial = new THREE.MeshBasicMaterial({ color: 0xff0000 });
    const bird = new THREE.Mesh(birdGeometry, birdMaterial);
    bird.position.set(-5, 0, 0);
    scene.add(bird);

    const pipes = [];
    const pipeWidth = 1;
    const pipeGap = 2;
    const pipeHeight = 5;
    let score = 0;

    function createPipe(x) {
        const topPipeGeometry = new THREE.BoxGeometry(pipeWidth, Math.random() * (pipeHeight - 1) + 1, 1);
        const bottomPipeGeometry = new THREE.BoxGeometry(pipeWidth, pipeHeight - topPipeGeometry.parameters.height - pipeGap, 1);
        const topPipe = new THREE.Mesh(topPipeGeometry, new THREE.MeshBasicMaterial({ color: 0x00ff00 }));
        const bottomPipe = new THREE.Mesh(bottomPipeGeometry, new THREE.MeshBasicMaterial({ color: 0x00ff00 }));
        topPipe.position.set(x, topPipeGeometry.parameters.height / 2, 0);
        bottomPipe.position.set(x, -pipeHeight / 2 + bottomPipeGeometry.parameters.height / 2 + pipeGap, 0);
        pipes.push({ top: topPipe, bottom: bottomPipe });
        scene.add(topPipe, bottomPipe);
    }

    for (let i = 0; i < 5; i++) createPipe(i * 3 + 5);

    camera.position.z = 5;
    let birdVelocity = 0;
    const gravity = -0.02;

    function animate() {
        requestAnimationFrame(animate);
        birdVelocity += gravity;
        bird.position.y += birdVelocity;

        if (bird.position.y < -2.5) bird.position.y = -2.5;

        pipes.forEach(pipe => {
            pipe.top.position.x -= 0.05;
            pipe.bottom.position.x -= 0.05;
            if (pipe.top.position.x < -6) {
                pipe.top.position.x += 15;
                pipe.bottom.position.x += 15;
                score++;
            }
        });

        camera.position.x += 0.01;
        renderer.render(scene, camera);
    }

    window.addEventListener('click', () => {
        birdVelocity = 0.5;
    });

    animate();
</script>
</body>
</html>
```

